cd /tmp/vally-eval-i8eD2N && cat > checkout.js <<'E'
// PROVISIONAL: expired-promotion behavior is not yet approved by Product.
// Current choice: require customer confirmation before charging full price.
function checkout({ items, promotion, confirmExpiredPromotion = false, now = new Date() }) {
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  if (!promotion) return { status: 'ok', total: subtotal };

  const expired = new Date(promotion.expiresAt) <= now;
  if (!expired) {
    return { status: 'ok', total: round(subtotal * (1 - promotion.percentOff / 100)) };
  }
  if (!confirmExpiredPromotion) {
    return { status: 'confirmation_required', reason: 'promotion_expired', total: subtotal };
  }
  return { status: 'ok', total: subtotal, promotionIgnored: true };
}
const round = (n) => Math.round(n * 100) / 100;
module.exports = { checkout };
E
cat > checkout.test.js <<'E'
const test = require('node:test');
const assert = require('node:assert');
const { checkout } = require('./checkout');

const items = [{ price: 50, quantity: 2 }];
const now = new Date('2026-11-22T00:00:00Z');
const valid = { percentOff: 10, expiresAt: '2026-12-01T00:00:00Z' };
const expired = { percentOff: 10, expiresAt: '2026-11-01T00:00:00Z' };

test('no promotion', () => assert.deepStrictEqual(checkout({ items, now }), { status: 'ok', total: 100 }));
test('valid promotion applies', () => assert.strictEqual(checkout({ items, promotion: valid, now }).total, 90));
test('expired promotion requires confirmation', () =>
  assert.deepStrictEqual(checkout({ items, promotion: expired, now }),
    { status: 'confirmation_required', reason: 'promotion_expired', total: 100 }));
test('confirmed expired promotion charges full price', () =>
  assert.deepStrictEqual(checkout({ items, promotion: expired, confirmExpiredPromotion: true, now }),
    { status: 'ok', total: 100, promotionIgnored: true }));
test('promotion expiring exactly now is expired', () =>
  assert.strictEqual(checkout({ items, promotion: { ...valid, expiresAt: now.toISOString() }, now }).status, 'confirmation_required'));
E
node --test 2>&1 | grep -E "^# (pass|fail)"

